int random_move() {
    object where;
    mapping exits;
    string *dirs;

    where = environment();

    command("say 师父叫我在此办一件大事。");

    /* trapped */
    if (!mapp(exits = where->query("exits")))
        return 0;

    if ((string)file_name(where) == "/d/village/hsroad2") {
        command("go south");
        return 1;
    }

    if ((string)file_name(where) == "/d/wudang/wdroad5") {
        command("go north");
        return 1;
    }

    dirs = keys(exits);
    if (sizeof(dirs) < 2) {
        command("go " + dirs[0]);
    } else {
        command("go " + dirs[random(sizeof(dirs))]);
    }
    return 1;
}

